import{Component}from'../../core/index.js';import{THREE}from'./geometry.js';
/** Own LED1 XBLUE,one external indicator behind three real windows. */
export class StatusLed extends Component{static kind='led';constructor({emitter,guide,leg,...options}){super(options);this.color=new THREE.Color(0x168aff);this.brightness=0;this.emitter=emitter;this.lens=guide;this.guide=guide;this.leg=leg;this.object3d.add(emitter,guide,leg);this.lensMaterial=guide.material;this.outputMaterials=[emitter.material,guide.material];for(const m of this.outputMaterials)m.emissive=new THREE.Color(0);}
set(value){const s=typeof value==='boolean'?{on:value}:value;if(!s||typeof s!=='object')throw new TypeError('status expects on/brightness');if(s.color!=null&&new THREE.Color(s.color).getHex()!==this.color.getHex())throw new RangeError('TimerCamera-X actual indicator is fixed blue');if(s.brightness!=null){if(!Number.isFinite(s.brightness))throw new TypeError('brightness must be finite');this.brightness=Math.max(0,Math.min(1,s.brightness));}else if(s.on!=null)this.brightness=s.on?1:0;for(const m of this.outputMaterials)m.emissive.copy(this.color).multiplyScalar(this.brightness*2);this.requestRender();return this.getState();}
handle(command){if(command.type==='led')return this.set(command);return super.handle(command);}getState(){return{color:'#168aff',brightness:this.brightness};}}
